-- F1_App: datos historicos reales F1, 2021-2026 (corte: 24 de noviembre de 2026).
-- Fuente: F1DB https://github.com/f1db/f1db | Licencia CC BY 4.0
-- 2021-2025: CSV F1DB replicados por https://github.com/TracingInsights/RaceData
-- 2026: fuentes originales F1DB YAML; actualizado al GP de Las Vegas 22/11/2026.
-- Qatar y Abu Dabi 2026 incluidos SOLO como calendario (sin resultados futuros).
-- No se inventan clasificaciones ni estadisticas. Compatible con el esquema PostgreSQL reconstruido.
-- Repetible: si se ejecuta dos veces actualiza registros importados en lugar de duplicarlos.
-- Nota: se agregan equipo_id y estado_resultado para conservar cambios de escuderia y DNF/DSQ.
BEGIN;
SET LOCAL statement_timeout = '0';
SET LOCAL search_path TO public;
DO $$
BEGIN
 IF to_regclass('public.piloto') IS NULL OR to_regclass('public.categoria') IS NULL OR
    to_regclass('public.equipo') IS NULL OR to_regclass('public.circuito') IS NULL OR
    to_regclass('public.temporada') IS NULL OR to_regclass('public.grandes_premios') IS NULL OR
    to_regclass('public.resultados') IS NULL OR to_regclass('public.pilotos_temporada') IS NULL OR
    to_regclass('public.equipos_temporada') IS NULL THEN
     RAISE EXCEPTION 'Faltan tablas. Ejecuta primero F1_App_Supabase_PostgreSQL.sql';
 END IF;
END $$;
ALTER TABLE public.piloto ADD COLUMN IF NOT EXISTS codigo_fuente text;
ALTER TABLE public.equipo ADD COLUMN IF NOT EXISTS codigo_fuente text;
ALTER TABLE public.circuito ADD COLUMN IF NOT EXISTS codigo_fuente text;
ALTER TABLE public.grandes_premios ADD COLUMN IF NOT EXISTS codigo_fuente text;
ALTER TABLE public.resultados ADD COLUMN IF NOT EXISTS equipo_id integer REFERENCES public.equipo(id_equipo);
ALTER TABLE public.resultados ADD COLUMN IF NOT EXISTS estado_resultado varchar(15);
CREATE UNIQUE INDEX IF NOT EXISTS f1_piloto_source_uq ON public.piloto(codigo_fuente);
CREATE UNIQUE INDEX IF NOT EXISTS f1_equipo_source_uq ON public.equipo(codigo_fuente);
CREATE UNIQUE INDEX IF NOT EXISTS f1_circuito_source_uq ON public.circuito(codigo_fuente);
CREATE UNIQUE INDEX IF NOT EXISTS f1_gp_source_uq ON public.grandes_premios(codigo_fuente);
CREATE INDEX IF NOT EXISTS f1_resultado_equipo_idx ON public.resultados(equipo_id);
INSERT INTO public.categoria(id_categoria,nombre) VALUES (1,'Formula 1') ON CONFLICT DO NOTHING;
INSERT INTO public.temporada(anio,finalizada)
VALUES (2021,1),(2022,1),(2023,1),(2024,1),(2025,1),(2026,0)
ON CONFLICT(anio) DO UPDATE SET finalizada=excluded.finalizada;



